def topo_sort(graph):
    indegree = {}
    adj = {}

    for node in graph:
        if node not in indegree:
            indegree[node] = 0
        if node not in adj:
            adj[node] = set()
        for nxt in graph[node]:
            if nxt not in adj:
                adj[nxt] = set()
            if nxt not in indegree:
                indegree[nxt] = 0
            if nxt not in adj[node]:
                adj[node].add(nxt)
                indegree[nxt] += 1

    import heapq
    heap = [n for n in indegree if indegree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) != len(indegree):
        raise ValueError("Döngü bulundu")

    return result
